 268 /**
 269  * Execute a format step
 270  * 
 271  * Formats and transforms data using templates and transformations
 272  */
 273 export async function executeFormatStep(
 274   step: FlowStep,
 275   input: Record<string, any>,
 276   context: ContextManager
 277 ): Promise<StepExecutionResult> {
 278   try {
 279     const {
 280       template,
 281       format = 'text',
 282       data,
 283       transformation,
 284     } = input;
 285 
 286     if (!data) {
 287       throw new StepValidationError('format', 'data parameter is required');
 288     }
 289 
 290     let output: any;
 291 
 292     // Apply transformation if specified
 293     const transformedData = transformation 
 294       ? applyTransformation(data, transformation)
 295       : data;
 296 
 297     // Format based on type
 298     switch (format) {
 299       case 'json':
 300         output = formatAsJSON(transformedData);
 301         break;
 302 
 303       case 'markdown':
 304         output = formatAsMarkdown(transformedData, template);
 305         break;
 306 
 307       case 'text':
 308         output = formatAsText(transformedData, template);
 309         break;
 310 
 311       case 'html':
 312         output = formatAsHTML(transformedData, template);
 313         break;
 314 
 315       case 'csv':
 316         output = formatAsCSV(transformedData);
 317         break;
 318 
 319       default:
 320         throw new StepValidationError('format', `Unsupported format: ${format}`);
 321     }
 322 
 323     return {
 324       output: {
 325         formatted: output,
 326         format,
 327       },
 328       metadata: {
 329         format,
 330         hasTemplate: !!template,
 331         hasTransformation: !!transformation,
 332       },
 333     };
 334   } catch (error) {
 335     console.error('Format step failed:', error);
 336     // Re-throw validation errors as-is
