 344 /**
 345  * Apply a transformation to data
 346  */
 347 function applyTransformation(data: any, transformation: string): any {
 348   try {
 349     // Support simple transformations
 350     switch (transformation) {
 351       case 'uppercase':
 352         return typeof data === 'string' ? data.toUpperCase() : data;
 353 
 354       case 'lowercase':
 355         return typeof data === 'string' ? data.toLowerCase() : data;
 356 
 357       case 'trim':
 358         return typeof data === 'string' ? data.trim() : data;
 359 
 360       case 'stringify':
 361         return JSON.stringify(data, null, 2);
 362 
 363       case 'parse':
 364         return typeof data === 'string' ? JSON.parse(data) : data;
 365 
 366       case 'flatten':
 367         return Array.isArray(data) ? data.flat() : data;
 368 
 369       case 'compact':
 370         return Array.isArray(data) ? data.filter(Boolean) : data;
 371 
 372       default:
 373         // Try to execute as a JavaScript expression
 374         // Note: This is potentially dangerous and should be sandboxed in production
 375         console.warn('Custom transformation not sandboxed:', transformation);
 376         return data;
 377     }
 378   } catch (error) {
 379     console.error('Transformation failed:', error);
 380     return data;
 381   }
 382 }
