 384 /**
 385  * Format data as JSON
 386  */
 387 function formatAsJSON(data: any): string {
 388   return JSON.stringify(data, null, 2);
 389 }
 390 
 391 /**
 392  * Format data as Markdown
 393  */
 394 function formatAsMarkdown(data: any, template?: string): string {
 395   if (template) {
 396     return interpolateTemplate(template, data);
 397   }
 398 
 399   // Default markdown formatting
 400   if (typeof data === 'string') {
 401     return data;
 402   }
 403 
 404   if (Array.isArray(data)) {
 405     return data.map((item, idx) => `${idx + 1}. ${formatAsMarkdown(item)}`).join('\n');
 406   }
 407 
 408   if (typeof data === 'object' && data !== null) {
 409     return Object.entries(data)
 410       .map(([key, value]) => `**${key}**: ${value}`)
 411       .join('\n\n');
 412   }
 413 
 414   return String(data);
 415 }
 416 
 417 /**
 418  * Format data as plain text
 419  */
 420 function formatAsText(data: any, template?: string): string {
 421   if (template) {
 422     return interpolateTemplate(template, data);
 423   }
 424 
 425   // Default text formatting
 426   if (typeof data === 'string') {
 427     return data;
 428   }
 429 
 430   if (Array.isArray(data)) {
 431     return data.join('\n');
 432   }
 433 
 434   if (typeof data === 'object' && data !== null) {
 435     return Object.entries(data)
 436       .map(([key, value]) => `${key}: ${value}`)
 437       .join('\n');
 438   }
 439 
 440   return String(data);
 441 }
 442 
 443 /**
 444  * Format data as HTML
 445  */
 446 function formatAsHTML(data: any, template?: string): string {
 447   if (template) {
 448     return interpolateTemplate(template, data);
 449   }
 450 
 451   // Default HTML formatting
 452   if (typeof data === 'string') {
 453     return `<p>${escapeHTML(data)}</p>`;
 454   }
 455 
 456   if (Array.isArray(data)) {
 457     const items = data.map(item => `<li>${escapeHTML(String(item))}</li>`).join('');
 458     return `<ul>${items}</ul>`;
 459   }
 460 
 461   if (typeof data === 'object' && data !== null) {
 462     const items = Object.entries(data)
 463       .map(([key, value]) => `<dt>${escapeHTML(key)}</dt><dd>${escapeHTML(String(value))}</dd>`)
 464       .join('');
 465     return `<dl>${items}</dl>`;
 466   }
 467 
 468   return `<p>${escapeHTML(String(data))}</p>`;
 469 }
 470 
 471 /**
 472  * Format data as CSV
 473  */
 474 function formatAsCSV(data: any): string {
 475   if (!Array.isArray(data)) {
 476     throw new Error('CSV format requires array data');
 477   }
 478 
 479   if (data.length === 0) {
 480     return '';
 481   }
 482 
 483   // Assume array of objects
 484   if (typeof data[0] === 'object' && data[0] !== null) {
 485     const headers = Object.keys(data[0]);
 486     const headerRow = headers.map(escapeCSV).join(',');
 487     const dataRows = data.map(row =>
 488       headers.map(header => escapeCSV(String(row[header] ?? ''))).join(',')
 489     );
 490     return [headerRow, ...dataRows].join('\n');
 491   }
 492 
 493   // Array of primitives
 494   return data.map(item => escapeCSV(String(item))).join(',');
 495 }
 496 
 497 /**
 498  * Interpolate template with data
 499  */
 500 function interpolateTemplate(template: string, data: any): string {
 501   return template.replace(/\{\{([^}]+)\}\}/g, (match, key) => {
 502     const trimmedKey = key.trim();
 503     const value = getNestedValue(data, trimmedKey);
 504     return value !== undefined ? String(value) : match;
 505   });
 506 }
 507 
 508 /**
 509  * Get nested value from object using dot notation
 510  */
 511 function getNestedValue(obj: any, path: string): any {
 512   return path.split('.').reduce((current, key) => current?.[key], obj);
 513 }
 514 
 515 /**
 516  * Escape HTML special characters
 517  */
 518 function escapeHTML(text: string): string {
 519   const map: Record<string, string> = {
 520     '&': '&amp;',
 521     '<': '&lt;',
 522     '>': '&gt;',
 523     '"': '&quot;',
 524     "'": '&#039;',
 525   };
 526   return text.replace(/[&<>"']/g, char => map[char]);
 527 }
 528 
 529 /**
 530  * Escape CSV values
 531  */
 532 function escapeCSV(value: string): string {
 533   if (value.includes(',') || value.includes('"') || value.includes('\n')) {
 534     return `"${value.replace(/"/g, '""')}"`;
 535   }
 536   return value;
 537 }
 538 
 539 /**
 540  * Custom error classes
 541  */
 542 export class StepExecutionError extends Error {
 543   public readonly stepType: string;
 544   public readonly stepName: string;
 545   public readonly cause?: any;
 546 
 547   constructor(stepType: string, stepName: string, cause?: any) {
 548     const message = cause instanceof Error 
 549       ? `${stepType} step "${stepName}" failed: ${cause.message}`
 550       : `${stepType} step "${stepName}" failed`;
 551     super(message);
 552     this.name = 'StepExecutionError';
 553     this.stepType = stepType;
 554     this.stepName = stepName;
 555     this.cause = cause;
 556   }
 557 }
 558 
 559 export class StepValidationError extends Error {
 560   public readonly stepType: string;
 561 
 562   constructor(stepType: string, message: string) {
 563     super(`${stepType} step validation failed: ${message}`);
 564     this.name = 'StepValidationError';
 565     this.stepType = stepType;
 566   }
 567 }
 568 
 569 export class UnsupportedStepTypeError extends Error {
 570   constructor(stepType: string) {
 571     super(`Unsupported step type: ${stepType}`);
 572     this.name = 'UnsupportedStepTypeError';
 573   }
 574 }
 575 
 576 /**
 577  * Export all step handlers
 578  */
 579 export const stepHandlers = {
 580   retrieve: executeRetrieveStep,
 581   generate: executeGenerateStep,
 582   tool: executeToolStep,
 583   format: executeFormatStep,
 584 };
 585 
