{"file_path": "dynamic-flows-sdk/src/core/sdk.ts", "initial_content": "/**
 * Main SDK Class for Dynamic Flows
 * 
 * Provides a unified interface for:
 * - Flow execution
 * - Tool registration
 * - RAG configuration
 * - Prompt execution
 */

import { Genkit } from 'genkit';
import { z } from 'zod';

export interface DynamicFlowsSDKConfig {
  ai: Genkit;
  enableTracing?: boolean;
  defaultTimeout?: number;
}

export interface FlowInput {
  flowName: string;
  payload: Record<string, any>;
  userId?: string;
  requestId?: string;
  enableTracing?: boolean;
}

export interface FlowOutput {
  success: boolean;
  output?: any;
  error?: string;
  executionId?: string;
  traceId?: string;
  duration?: number;
}

export interface RAGConfig {
  client: any; // QdrantClient or similar
  collectionName: string;
  embeddingModel?: string;
}

export interface Tool {
  name: string;
  description: string;
  inputSchema: z.ZodSchema;
  outputSchema: z.ZodSchema;
  handler: (input: any) => Promise<any>;
}

/**
 * Main SDK class
 */
export class DynamicFlowsSDK {
  private ai: Genkit;
  private enableTracing: boolean;
  private defaultTimeout: number;
  private tools: Map<string, Tool> = new Map();
  private ragConfig?: RAGConfig;
  private flowConfigs: Map<string, any> = new Map();

  constructor(config: DynamicFlowsSDKConfig) {
    this.ai = config.ai;
    this.enableTracing = config.enableTracing ?? true;
    this.defaultTimeout = config.defaultTimeout ?? 60000;
  }

  /**
   * Execute a dynamic flow
   */
  async executeFlow(input: FlowInput): Promise<FlowOutput> {
    const { dynamicFlowExecutor } = await import('../dynamic-flow/executor');

    return await dynamicFlowExecutor({
      flowName: input.flowName,
      payload: input.payload,
      userId: input.userId,
      requestId: input.requestId,
      enableTracing: input.enableTracing ?? this.enableTracing,
    });
  }

  /**
   * Register a custom tool
   */
  registerTool(tool: Tool): void {
    this.tools.set(tool.name, tool);
  }

  /**
   * Get a registered tool
   */
  getTool(name: string): Tool | undefined {
    return this.tools.get(name);
  }

  /**
   * Get all registered tools
   */
  getAllTools(): Tool[] {
    return Array.from(this.tools.values());
  }

  /**
   * Configure RAG integration
   */
  configureRAG(config: RAGConfig): void {
    this.ragConfig = config;
  }

  /**
   * Get RAG configuration
   */
  getRAGConfig(): RAGConfig | undefined {
    return this.ragConfig;
  }

  /**
   * Execute a prompt directly
   */
  async executePrompt(prompt: any, input: any): Promise<any> {
    return await prompt(input);
  }

  /**
   * Register a flow configuration
   */
  registerFlowConfig(config: any): void {
    this.flowConfigs.set(config.name, config);
  }

  /**
   * Get a flow configuration
   */
  getFlowConfig(name: string): any | undefined {
    return this.flowConfigs.get(name);
  }

  /**
   * Get Genkit instance
   */
  getAI(): Genkit {
    return this.ai;
  }
}

/**
 * Helper function to create a tool
 */
export function createTool(config: Tool): Tool {
  return config;
}

/**
 * Helper function to create Genkit instance
 */
export { ai as createGenkitInstance } from './genkit';
"}

