 * Flow Registry - In-memory storage for flow configurations
 * 
 * This is a simple in-memory registry for the standalone SDK.
 * Users can extend this with their own storage adapters (database, file system, etc.)
 */

import { FlowConfiguration } from '../models/flow-config';

/**
 * In-memory flow configuration registry
 */
const flowRegistry = new Map<string, FlowConfiguration>();

/**
 * Register a flow configuration
 */
export function registerFlowConfig(config: FlowConfiguration): void {
  flowRegistry.set(config.name, config);
}

/**
 * Get a flow configuration by name
 */
export function getFlowConfigFromRegistry(name: string): Promise<FlowConfiguration | null> {
  return Promise.resolve(flowRegistry.get(name) || null);
}

/**
 * Get all registered flow configurations
 */
export function getAllFlowConfigs(): FlowConfiguration[] {
  return Array.from(flowRegistry.values());
}

/**
 * Check if a flow is registered
 */
export function hasFlowConfig(name: string): boolean {
  return flowRegistry.has(name);
}

/**
 * Remove a flow configuration
 */
export function unregisterFlowConfig(name: string): boolean {
  return flowRegistry.delete(name);
}

/**
 * Clear all flow configurations
 */
export function clearFlowRegistry(): void {
  flowRegistry.clear();
}

/**
 * Storage adapter interface for custom implementations
 */
export interface FlowStorageAdapter {
  get(name: string): Promise<FlowConfiguration | null>;
  set(config: FlowConfiguration): Promise<void>;
  delete(name: string): Promise<boolean>;
  getAll(): Promise<FlowConfiguration[]>;
}

/**
 * Set a custom storage adapter
 */
let customAdapter: FlowStorageAdapter | null = null;

export function setFlowStorageAdapter(adapter: FlowStorageAdapter): void {
  customAdapter = adapter;
}

/**
 * Get flow configuration with adapter support
 */
export async function getFlowConfiguration(name: string): Promise<FlowConfiguration | null> {
  if (customAdapter) {
    return await customAdapter.get(name);
  }
  return await getFlowConfigFromRegistry(name);
}
"}

{"file_path": "dynamic-flows-sdk/src/utils/model-selector.ts", "initial_content": "/**
 * Model Selection Utilities
 * 
 * Helps select appropriate models based on task requirements
 */

/**
 * Ollama model configurations
 */
export const OLLAMA_MODELS = {
  // Fast, efficient for basic text operations
  GEMMA_2B: 'ollama/gemma:2b',

  // Strong reasoning and structured output
  PHI3_MINI: 'ollama/phi3:mini',

  // High quality for complex academic tasks
  LLAMA3_8B: 'ollama/llama3:8b',
} as const;

/**
 * Model recommendations by task category
 */
export const MODEL_BY_TASK = {
  // 🔄 Conversion & Processing: Fast text transformation
  CONVERSION: OLLAMA_MODELS.GEMMA_2B,

  // ✍️ Text Generation & Writing: Basic to moderate creativity
  TEXT_GENERATION: OLLAMA_MODELS.GEMMA_2B,

  // 📊 Reports & Documentation: Structured output, formatting
  REPORTS: OLLAMA_MODELS.PHI3_MINI,

  // ✅ Checking & Analysis: Reasoning and linguistic analysis
  ANALYSIS: OLLAMA_MODELS.PHI3_MINI,

  // 🎯 Specific Tasks: Precise structured output (JSON, PlantUML, etc.)
  STRUCTURED: OLLAMA_MODELS.PHI3_MINI,

  // 🎓 Academic & Research: Complex reasoning, high quality (use with RAG)
  ACADEMIC: OLLAMA_MODELS.LLAMA3_8B,
} as const;

/**
 * Select a model based on task type
 */
export function selectModelForTask(taskType: keyof typeof MODEL_BY_TASK): string {
  return MODEL_BY_TASK[taskType];
}

/**
 * Get model recommendations for a task description
 */
export function getModelRecommendation(taskDescription: string): string {
  const description = taskDescription.toLowerCase();

  if (description.includes('academic') || description.includes('research') || description.includes('complex')) {
    return MODEL_BY_TASK.ACADEMIC;
  }

  if (description.includes('report') || description.includes('document') || description.includes('structured')) {
    return MODEL_BY_TASK.REPORTS;
  }

  if (description.includes('check') || description.includes('analyze') || description.includes('validate')) {
    return MODEL_BY_TASK.ANALYSIS;
  }

  if (description.includes('convert') || description.includes('transform') || description.includes('format')) {
    return MODEL_BY_TASK.CONVERSION;
  }

  // Default to text generation
  return MODEL_BY_TASK.TEXT_GENERATION;
}
"}

{"file_path": "dynamic-flows-sdk/src/utils/error-handler.ts", "initial_content": "/**
 * Error Handling Utilities
 * 
 * Standardized error handling for the SDK
 */

/**
 * Base SDK Error
 */
export class SDKError extends Error {
  public readonly code: string;
  public readonly details?: any;

  constructor(message: string, code: string, details?: any) {
    super(message);
    this.name = 'SDKError';
    this.code = code;
    this.details = details;
  }
}

/**
 * Flow not found error
 */
export class FlowNotFoundError extends SDKError {
  constructor(flowName: string) {
    super(
      `Flow configuration not found: ${flowName}`,
      'FLOW_NOT_FOUND',
      { flowName }
    );
    this.name = 'FlowNotFoundError';
  }
}

/**
 * Step execution error
 */
export class StepExecutionError extends SDKError {
  constructor(stepName: string, cause: Error) {
    super(
      `Step execution failed: ${stepName}`,
      'STEP_EXECUTION_ERROR',
      { stepName, cause: cause.message }
    );
    this.name = 'StepExecutionError';
  }
}

/**
 * Validation error
 */
export class ValidationError extends SDKError {
  constructor(message: string, details?: any) {
    super(message, 'VALIDATION_ERROR', details);
    this.name = 'ValidationError';
  }
}

/**
 * Configuration error
 */
export class ConfigurationError extends SDKError {
  constructor(message: string, details?: any) {
    super(message, 'CONFIGURATION_ERROR', details);
    this.name = 'ConfigurationError';
  }
}

/**
 * Timeout error
 */
export class TimeoutError extends SDKError {
  constructor(operation: string, timeout: number) {
    super(
      `Operation timed out: ${operation} (${timeout}ms)`,
      'TIMEOUT_ERROR',
      { operation, timeout }
    );
    this.name = 'TimeoutError';
  }
}

/**
 * Error handler that standardizes error responses
 */
export function handleError(error: unknown): SDKError {
  if (error instanceof SDKError) {
    return error;
  }

  if (error instanceof Error) {
    return new SDKError(error.message, 'UNKNOWN_ERROR', { originalError: error.name });
  }

  return new SDKError(
    'An unknown error occurred',
    'UNKNOWN_ERROR',
    { error: String(error) }
  );
}
"}

{"file_path": "dynamic-flows-sdk/src/utils/rag-adapter.ts", "initial_content": "/**
 * RAG (Retrieval-Augmented Generation) Adapter
 * 
 * Provides abstraction for vector database operations
 */

/**
 * RAG retrieval options
 */
export interface RetrievalOptions {
  topK?: number;
  minScore?: number;
  projectId?: string;
  userId?: string;
  includeTypes?: string[];
  useCache?: boolean;
  rerank?: boolean;
  rerankStrategy?: 'hybrid' | 'semantic' | 'keyword';
}

/**
 * Retrieved source information
 */
export interface RetrievedSource {
  content: string;
  score: number;
  sourceFile?: string;
  type: string;
  metadata?: Record<string, any>;
}

/**
 * Retrieval result
 */
export interface RetrievalResult {
  context: string;
  sources: RetrievedSource[];
}

/**
 * RAG adapter interface
 */
export interface RAGAdapter {
  retrieve(query: string, options?: RetrievalOptions): Promise<RetrievalResult>;
  index(documents: any[]): Promise<void>;
  delete(ids: string[]): Promise<void>;
}

/**
 * Default RAG adapter (returns empty results if no adapter is configured)
 */
export class DefaultRAGAdapter implements RAGAdapter {
  async retrieve(query: string, options?: RetrievalOptions): Promise<RetrievalResult> {
    console.warn('No RAG adapter configured. Returning empty context.');
    return {
      context: '',
      sources: [],
    };
  }

  async index(documents: any[]): Promise<void> {
    console.warn('No RAG adapter configured. Indexing skipped.');
  }

  async delete(ids: string[]): Promise<void> {
    console.warn('No RAG adapter configured. Deletion skipped.');
  }
}

/**
 * Global RAG adapter instance
 */
let ragAdapter: RAGAdapter = new DefaultRAGAdapter();

/**
 * Set the RAG adapter
 */
export function setRAGAdapter(adapter: RAGAdapter): void {
  ragAdapter = adapter;
}

/**
 * Get the current RAG adapter
 */
export function getRAGAdapter(): RAGAdapter {
  return ragAdapter;
}

/**
 * Retrieve context using the configured adapter
 */
export async function retrieveContext(
  query: string,
  options?: RetrievalOptions
): Promise<RetrievalResult> {
  return await ragAdapter.retrieve(query, options);
}
"}

