{"file_path": "dynamic-flows-sdk/src/utils/tool-registry.ts", "initial_content": "/**
 * Tool Registry - Manages tool registration and execution
 * 
 * Provides a centralized registry for tools that can be used in flows
 */

import { z } from 'zod';

/**
 * Tool definition
 */
export interface ToolDefinition {
  name: string;
  description: string;
  inputSchema: z.ZodSchema;
  outputSchema: z.ZodSchema;
  handler: (input: any) => Promise<any>;
}

/**
 * Tool execution result
 */
export interface ToolExecutionResult {
  success: boolean;
  result?: any;
  error?: string;
}

/**
 * In-memory tool registry
 */
const toolRegistry = new Map<string, ToolDefinition>();

/**
 * Register a tool
 */
export function registerTool(tool: ToolDefinition): void {
  toolRegistry.set(tool.name, tool);
}

/**
 * Get a tool by name
 */
export function getTool(name: string): ToolDefinition | undefined {
  return toolRegistry.get(name);
}

/**
 * Get all registered tools
 */
export function getAllTools(): ToolDefinition[] {
  return Array.from(toolRegistry.values());
}

/**
 * Check if a tool is registered
 */
export function hasTool(name: string): boolean {
  return toolRegistry.has(name);
}

/**
 * Unregister a tool
 */
export function unregisterTool(name: string): boolean {
  return toolRegistry.delete(name);
}

/**
 * Clear all tools
 */
export function clearToolRegistry(): void {
  toolRegistry.clear();
}

/**
 * Execute a tool from the registry
 */
export async function executeToolFromRegistry(
  toolName: string,
  parameters: Record<string, any>,
  timeout?: number
): Promise<any> {
  const tool = toolRegistry.get(toolName);

  if (!tool) {
    throw new Error(`Tool not found: ${toolName}`);
  }

  try {
    // Validate input
    const validatedInput = tool.inputSchema.parse(parameters);

    // Execute with timeout if specified
    let result;
    if (timeout) {
      result = await executeWithTimeout(
        tool.handler(validatedInput),
        timeout,
        `Tool ${toolName} execution timed out`
      );
    } else {
      result = await tool.handler(validatedInput);
    }

    // Validate output
    const validatedOutput = tool.outputSchema.parse(result);

    return validatedOutput;
  } catch (error) {
    console.error(`Tool execution failed: ${toolName}`, error);
    throw error;
  }
}

/**
 * Execute a promise with timeout
 */
function executeWithTimeout<T>(
  promise: Promise<T>,
  timeout: number,
  errorMessage: string
): Promise<T> {
  return Promise.race([
    promise,
    new Promise<T>((_, reject) =>
      setTimeout(() => reject(new Error(errorMessage)), timeout)
    ),
  ]);
}
"}

