{"file_path": "dynamic-flows-sdk/examples/basic-flow.ts", "initial_content": "/**
 * Basic Flow Example
 * 
 * Demonstrates simple text generation using the Dynamic Flows SDK
 */

import { genkit } from 'genkit';
import { ollama } from 'genkitx-ollama';
import { DynamicFlowsSDK } from '../src/core/sdk';
import { registerFlowConfig } from '../src/utils/flow-registry';
import { z } from 'zod';

async function main() {
  // 1. Initialize Genkit with Ollama
  const ai = genkit({
    plugins: [
      ollama({
        models: [
          { name: 'gemma:2b', type: 'generate' },
          { name: 'phi3:mini', type: 'generate' },
        ],
        serverAddress: 'http://localhost:11434',
      }),
    ],
  });

  // 2. Create SDK instance
  const sdk = new DynamicFlowsSDK({
    ai,
    enableTracing: true,
  });

  // 3. Define a simple flow configuration
  const textGeneratorFlow = {
    id: 'text-generator',
    name: 'text-generator',
    version: '1.0.0',
    description: 'Simple text generation flow',
    status: 'active' as const,
    category: 'generation',

    // Input schema
    inputSchema: z.object({
      prompt: z.string().describe('The text prompt'),
      maxTokens: z.number().optional().default(500),
    }),

    // Output schema
    outputSchema: z.object({
      text: z.string().describe('Generated text'),
      model: z.string().describe('Model used'),
    }),

    // Flow steps
    steps: [
      {
        id: 'generate-text',
        name: 'Generate Text',
        type: 'GENERATE' as const,
        description: 'Generate text using LLM',

        inputMapping: {
          prompt: '{{input.prompt}}',
          maxTokens: '{{input.maxTokens}}',
          model: 'ollama/gemma:2b',
        },

        outputMapping: {
          text: 'text',
          model: 'model',
        },

        inputSchema: z.object({
          prompt: z.string(),
          maxTokens: z.number().optional(),
          model: z.string(),
        }),

        outputSchema: z.object({
          text: z.string(),
          model: z.string(),
        }),
      },
    ],

    metadata: {
      author: 'SDK User',
      tags: ['text-generation', 'example'],
    },

    createdAt: new Date(),
    updatedAt: new Date(),
  };

  // 4. Register the flow
  registerFlowConfig(textGeneratorFlow);

  // 5. Execute the flow
  console.log('Executing flow...\n');

  const result = await sdk.executeFlow({
    flowName: 'text-generator',
    payload: {
      prompt: 'Write a haiku about artificial intelligence',
      maxTokens: 100,
    },
  });

  // 6. Display results
  if (result.success) {
    console.log('✅ Flow executed successfully!\n');
    console.log('Generated Text:');
    console.log(result.output.text);
    console.log('\nModel:', result.output.model);
    console.log('Duration:', result.duration, 'ms');
  } else {
    console.error('❌ Flow execution failed:', result.error);
  }
}

// Run the example
main().catch(console.error);
"}

