      }),
    ],
  });

  const sdk = new DynamicFlowsSDK({ ai });

  // 2. Register custom tools

  // Tool 1: Word Counter
  registerTool({
    name: 'count-words',
    description: 'Counts words in a text',
    inputSchema: z.object({
      text: z.string(),
    }),
    outputSchema: z.object({
      count: z.number(),
      text: z.string(),
    }),
    handler: async (input) => {
      const words = input.text.trim().split(/\s+/).filter(Boolean);
      return {
        count: words.length,
        text: input.text,
      };
    },
  });

  // Tool 2: Text Analyzer
  registerTool({
    name: 'analyze-text',
    description: 'Analyzes text statistics',
    inputSchema: z.object({
      text: z.string(),
    }),
    outputSchema: z.object({
      words: z.number(),
      characters: z.number(),
      sentences: z.number(),
      avgWordLength: z.number(),
    }),
    handler: async (input) => {
      const words = input.text.trim().split(/\s+/).filter(Boolean);
      const sentences = input.text.split(/[.!?]+/).filter(Boolean);
      const characters = input.text.replace(/\s/g, '').length;

      return {
        words: words.length,
        characters,
        sentences: sentences.length,
        avgWordLength: characters / (words.length || 1),
      };
    },
  });

  // 3. Define flow using custom tools
  const toolFlow = {
    id: 'text-analysis-flow',
    name: 'text-analysis-flow',
    version: '1.0.0',
    description: 'Analyzes and enhances text',
    status: 'active' as const,
    category: 'analysis',

    inputSchema: z.object({
      text: z.string(),
    }),

    outputSchema: z.object({
      original: z.string(),
      enhanced: z.string(),
      statistics: z.any(),
    }),

    steps: [
      // Step 1: Analyze original text
      {
        id: 'analyze-original',
        name: 'Analyze Original',
        type: 'TOOL' as const,
        description: 'Analyze the original text',

        inputMapping: {
          toolName: 'analyze-text',
          parameters: {
            text: '{{input.text}}',
          },
        },

        outputMapping: {
          originalStats: 'result',
        },

        inputSchema: z.object({
          toolName: z.string(),
          parameters: z.any(),
        }),

        outputSchema: z.object({
          result: z.any(),
        }),
      },

      // Step 2: Enhance text with AI
      {
        id: 'enhance-text',
        name: 'Enhance Text',
        type: 'GENERATE' as const,
        description: 'Enhance the text',

        inputMapping: {
          prompt: 'Improve this text while keeping its meaning: {{input.text}}',
          model: 'ollama/phi3:mini',
        },

        outputMapping: {
          enhanced: 'text',
        },

        inputSchema: z.object({
          prompt: z.string(),
          model: z.string(),
        }),

        outputSchema: z.object({
          text: z.string(),
        }),
      },

      // Step 3: Analyze enhanced text
      {
        id: 'analyze-enhanced',
        name: 'Analyze Enhanced',
        type: 'TOOL' as const,
        description: 'Analyze the enhanced text',

        inputMapping: {
          toolName: 'analyze-text',
          parameters: {
            text: '{{enhanced}}',
          },
        },

        outputMapping: {
          enhancedStats: 'result',
        },

        inputSchema: z.object({
          toolName: z.string(),
          parameters: z.any(),
        }),

        outputSchema: z.object({
          result: z.any(),
        }),
      },
    ],

    metadata: {
      author: 'SDK User',
      tags: ['tools', 'analysis'],
    },

    createdAt: new Date(),
    updatedAt: new Date(),
  };

  // 4. Register and execute
  registerFlowConfig(toolFlow);

  console.log('Executing tool-based flow...\n');

  const result = await sdk.executeFlow({
    flowName: 'text-analysis-flow',
    payload: {
      text: 'AI is cool. It helps us. We like it.',
    },
  });

  // 5. Display results
  if (result.success) {
    console.log('✅ Flow executed successfully!\n');
    console.log('Original:', result.output.original);
    console.log('\nOriginal Stats:', result.output.statistics.original);
    console.log('\nEnhanced:', result.output.enhanced);
    console.log('\nEnhanced Stats:', result.output.statistics.enhanced);
  } else {
    console.error('❌ Flow failed:', result.error);
  }
}

main().catch(console.error);
"}

{"file_path": "dynamic-flows-sdk/examples/README.md", "initial_content": "# Dynamic Flows SDK Examples

This directory contains example implementations demonstrating various features of the Dynamic Flows SDK.

## Prerequisites

1. Install dependencies:
```bash
cd dynamic-flows-sdk
npm install
```

2. Ensure Ollama is running:
```bash
# Start Ollama server
ollama serve

# Pull required models
ollama pull gemma:2b
ollama pull phi3:mini
ollama pull llama3:8b
```

## Examples

### 1. Basic Flow (`basic-flow.ts`)

Demonstrates simple text generation using a single-step flow.

**Features:**
- Flow configuration and registration
- Simple text generation
- Basic input/output handling

**Run:**
```bash
tsx examples/basic-flow.ts
```

### 2. RAG Flow (`rag-flow.ts`)

Shows how to implement RAG (Retrieval-Augmented Generation) with vector database integration.

**Features:**
- Multi-step flow (retrieve → generate)
- Custom RAG adapter implementation
- Context-aware generation
- Source tracking

**Run:**
```bash
tsx examples/rag-flow.ts
```

**Note:** This example uses a mock RAG adapter. To use a real vector database:

```typescript
import { QdrantClient } from '@qdrant/js-client-rest';

class QdrantRAGAdapter implements RAGAdapter {
  private client: QdrantClient;

  constructor(url: string) {
    this.client = new QdrantClient({ url });
  }

  async retrieve(query: string, options?: RetrievalOptions): Promise<RetrievalResult> {
    // Implement actual Qdrant search
    const results = await this.client.search('collection_name', {
      vector: await this.embedQuery(query),
      limit: options?.topK || 5,
    });

    return {
      context: results.map(r => r.payload.content).join('\n\n'),
      sources: results.map(r => ({
        content: r.payload.content,
        score: r.score,
        type: 'document',
      })),
    };
  }

  // ... implement other methods
}
```

### 3. Custom Tools (`custom-tools.ts`)

Demonstrates creating and using custom tools in flows.

**Features:**
- Custom tool registration
- Tool execution in flows
- Multi-step flow with tool integration
- Text analysis and enhancement pipeline

**Run:**
```bash
tsx examples/custom-tools.ts
```

## Creating Your Own Flow

Here's a template for creating a custom flow:

```typescript
import { genkit } from 'genkit';
import { ollama } from 'genkitx-ollama';
import { DynamicFlowsSDK } from '@arkan/dynamic-flows-sdk';
import { registerFlowConfig } from '@arkan/dynamic-flows-sdk/utils';
import { z } from 'zod';

async function main() {
  // 1. Initialize
  const ai = genkit({
    plugins: [
      ollama({
        models: [{ name: 'gemma:2b', type: 'generate' }],
        serverAddress: 'http://localhost:11434',
      }),
    ],
  });

  const sdk = new DynamicFlowsSDK({ ai });

  // 2. Define flow configuration
  const myFlow = {
    id: 'my-flow',
    name: 'my-flow',
    version: '1.0.0',
    description: 'My custom flow',
    status: 'active' as const,
    category: 'custom',

    inputSchema: z.object({
      // Define your inputs
    }),

    outputSchema: z.object({
      // Define your outputs
    }),

    steps: [
      // Define your steps
      {
        id: 'step1',
        name: 'My Step',
        type: 'GENERATE', // or 'RETRIEVE', 'TOOL', 'FORMAT'
        description: 'Description',
        inputMapping: { /* map inputs */ },
        outputMapping: { /* map outputs */ },
        inputSchema: z.object({ /* ... */ }),
        outputSchema: z.object({ /* ... */ }),
      },
    ],

    metadata: {
      author: 'Your Name',
      tags: ['custom'],
    },

    createdAt: new Date(),
    updatedAt: new Date(),
  };

  // 3. Register and execute
  registerFlowConfig(myFlow);

  const result = await sdk.executeFlow({
    flowName: 'my-flow',
    payload: { /* your inputs */ },
  });

  console.log(result);
}

main().catch(console.error);
```

## Step Types

### GENERATE
Generates text using an LLM.

```typescript
{
  type: 'GENERATE',
  inputMapping: {
    prompt: 'Your prompt here',
    model: 'ollama/gemma:2b',
    temperature: 0.7,
    maxTokens: 500,
  },
}
```

### RETRIEVE
Retrieves context from a vector database (requires RAG adapter).

```typescript
{
  type: 'RETRIEVE',
  inputMapping: {
    query: '{{input.query}}',
    topK: 5,
    minScore: 0.7,
  },
}
```

### TOOL
Executes a registered tool.

```typescript
{
  type: 'TOOL',
  inputMapping: {
    toolName: 'my-tool',
    parameters: {
      param1: '{{input.value}}',
    },
  },
}
```

### FORMAT
Formats and transforms data.

```typescript
{
  type: 'FORMAT',
  inputMapping: {
    data: '{{stepOutput}}',
    format: 'json', // or 'markdown', 'text', 'html', 'csv'
    template: 'Optional template string with {{placeholders}}',
  },
}
```

## Variable Interpolation

Use double curly braces to reference variables:

- `{{input.field}}` - Input field
- `{{stepId.field}}` - Output from a previous step
- `{{variableName}}` - Any variable in context

## Troubleshooting

### Ollama Connection Error
Ensure Ollama is running on the correct port:
```bash
ollama serve --host 0.0.0.0:11434
```

### Model Not Found
Pull the required model:
```bash
ollama pull gemma:2b
```

### Flow Not Found
Ensure you've registered the flow before executing:
```typescript
registerFlowConfig(myFlow);
```

## Next Steps

- Read the [API documentation](../README.md)
- Explore the [source code](../src)
- Create your own custom tools and flows
- Integrate with your vector database for RAG
"}

